package qr

import (
	"encoding/json"
	"errors"
	"os"
	"strings"
	"testing"
	"unicode/utf8"
)

// vector is one symbol encoded by ui/src/lib/qr.ts. The file was generated by
// running qr.ts under node; the point of comparing against it is that the
// terminal and the pairing screen must show the same code, mask included.
type vector struct {
	Text string   `json:"text"`
	Size int      `json:"size"`
	Rows []string `json:"rows"`
}

func TestMatchesTypeScriptEncoder(t *testing.T) {
	raw, err := os.ReadFile("testdata/vectors.json")
	if err != nil {
		t.Fatal(err)
	}
	var vs []vector
	if err := json.Unmarshal(raw, &vs); err != nil {
		t.Fatal(err)
	}
	if len(vs) == 0 {
		t.Fatal("no vectors")
	}
	for _, v := range vs {
		c, err := Encode(v.Text)
		if err != nil {
			t.Fatalf("Encode(%d bytes): %v", len(v.Text), err)
		}
		if c.Size != v.Size {
			t.Fatalf("Encode(%q): size %d, qr.ts %d", v.Text, c.Size, v.Size)
		}
		for y, row := range v.Rows {
			for x, ch := range row {
				if c.Dark(x, y) != (ch == '1') {
					t.Fatalf("Encode(%q): module (%d,%d) differs from qr.ts", v.Text, x, y)
				}
			}
		}
	}
}

func TestMaxLength(t *testing.T) {
	if _, err := Encode(strings.Repeat("a", MaxBytes)); err != nil {
		t.Fatalf("%d bytes: %v", MaxBytes, err)
	}
	if _, err := Encode(strings.Repeat("a", MaxBytes+1)); !errors.Is(err, ErrTooLong) {
		t.Fatalf("%d bytes: got %v, want ErrTooLong", MaxBytes+1, err)
	}
}

func TestTerminal(t *testing.T) {
	c, err := Encode("HELLO WORLD")
	if err != nil {
		t.Fatal(err)
	}
	const quiet = 2
	out := c.Terminal(quiet)
	lines := strings.Split(strings.TrimSuffix(out, "\n"), "\n")
	n := c.Size + 2*quiet
	if want := (n + 1) / 2; len(lines) != want {
		t.Fatalf("%d lines, want %d", len(lines), want)
	}
	for i, l := range lines {
		if utf8.RuneCountInString(l) != n {
			t.Fatalf("line %d is %d cells wide, want %d", i, utf8.RuneCountInString(l), n)
		}
	}
	// The quiet zone is light, and light is drawn as a full block.
	if lines[0] != strings.Repeat("█", n) {
		t.Fatalf("top quiet line = %q", lines[0])
	}
	// With quiet 2, line 1 holds symbol rows 0 and 1, whose first column is
	// the finder's dark outer ring: dark over dark is drawn blank.
	if r := []rune(lines[1]); r[quiet] != ' ' {
		t.Fatalf("finder corner drawn as %q", r[quiet])
	}
}
